package com.streamcraft.core.runtime;
import com.streamcraft.core.model.DataEntity; import com.streamcraft.core.model.PipelineNode; import com.streamcraft.shared.file.HdfsFileSourceConfig; import com.streamcraft.shared.file.HdfsFileSourceConfigParser; import org.apache.flink.api.common.eventtime.WatermarkStrategy; import org.apache.flink.streaming.api.datastream.DataStream; import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
public class HdfsFileSourceFactory { public DataStream<DataEntity> create(StreamExecutionEnvironment env,PipelineNode node){HdfsFileSourceConfig c=HdfsFileSourceConfigParser.parse(node.config(),IllegalArgumentException::new);return env.fromSource(new HdfsFileSource(c),WatermarkStrategy.noWatermarks(),node.name());} }
